import{_ as o,C as a,o as n,c as i,a3 as d,E as l,w as c,j as e,a as r}from"./chunks/framework.4Whkfpju.js";const g="/versions/v0.19.94/screens/settings/settings_menu.png",p="/versions/v0.19.94/screens/settings/firmware_menu.png",h="/versions/v0.19.94/screens/settings/usb_devices.png",m="/versions/v0.19.94/screens/settings/usb_devices_power.png",u="/versions/v0.19.94/screens/settings/migrate_all_confirm.png",f="/versions/v0.19.94/screens/settings/migrate_all_progress.png",v="/versions/v0.19.94/screens/settings/migrate_all_summary.png",A=JSON.parse('{"title":"Settings","description":"","frontmatter":{},"headers":[],"relativePath":"settings/index.md","filePath":"settings/index.md"}'),w={name:"settings/index.md"};function b(S,t,y,_,j,P){const s=a("ManualRelated");return n(),i("div",null,[t[1]||(t[1]=d('<h1 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h1><p><img src="'+g+'" alt="Settings menu" class="screen"></p><p>Rows that open another screen show <strong>&gt;</strong> on the right. <strong>Migrate All Projects</strong> shows an <strong>arrow out of a tray</strong> because Select starts the update.</p><p>These settings belong to <strong>this S32</strong>, not to the open project. Clock, default MIDI channel, and the encoder-button shortcut live under <a href="./../projects/#project-settings">Project Settings</a>.</p><table tabindex="0"><thead><tr><th>Item</th><th>Purpose</th></tr></thead><tbody><tr><td>Note Names</td><td>Octave convention for on-screen note names (Middle C as C3 or C4)</td></tr><tr><td><a href="./storage-info">Storage Info</a></td><td>Storage usage, microSD status, format storage</td></tr><tr><td>Firmware</td><td>Current version and USB firmware update</td></tr><tr><td><a href="#usb-devices">USB Devices</a></td><td>What is connected to the USB Host port, and the power it asks for</td></tr><tr><td><a href="#migrate-all-projects">Migrate All Projects</a></td><td>Update every out-of-date project on internal storage and microSD in one pass</td></tr></tbody></table><h2 id="note-names" tabindex="-1">Note Names <a class="header-anchor" href="#note-names" aria-label="Permalink to &quot;Note Names&quot;">​</a></h2><p>Octave convention for on-screen note names (C3 vs C4). Applies to device parameters (Seed root, Euclid layer notes, Step Seq notes, Envelope key) and the <strong>POLY AT</strong> macro <strong>Note</strong> field on Perform and in macro edit.</p><p>Black keys have one fixed spelling in note names: <strong>C#</strong>, <strong>E♭</strong>, <strong>F#</strong>, <strong>A♭</strong>, <strong>B♭</strong> — for example <strong>C#2</strong> and <strong>A♭3</strong>. It does not change with the project or a Scaler key. A Scaler&#39;s <strong>Key</strong> parameter is a key name, not a note, so it uses standard key spelling: <strong>D♭</strong>, <strong>E♭</strong>, <strong>A♭</strong>, <strong>B♭</strong>, with <strong>F#</strong> kept sharp.</p><p>This stays on the box so note names do not jump when you load another project.</p><h2 id="firmware" tabindex="-1">Firmware <a class="header-anchor" href="#firmware" aria-label="Permalink to &quot;Firmware&quot;">​</a></h2><p><img src="'+p+'" alt="Firmware" class="screen"></p><ul><li><strong>Version</strong> — current firmware version (display only; Select does nothing)</li><li><strong>Firmware Update</strong> — USB update flow</li></ul><p>To erase all stored projects and format storage, use <a href="./storage-info">Storage Info</a> → <strong>Format Storage</strong> (not the Firmware menu).</p><h2 id="usb-devices" tabindex="-1">USB Devices <a class="header-anchor" href="#usb-devices" aria-label="Permalink to &quot;USB Devices&quot;">​</a></h2><p><strong>Main Menu → Settings → USB Devices</strong> shows what is connected to the <strong>USB Host</strong> port.</p><p><img src="'+h+'" alt="USB Devices list" class="screen"></p><p>Each device sits under its hub. A hub inside another hub is indented one more step. Every row shows the power that device asks for. The list updates when you plug or unplug a device.</p><p><img src="'+m+'" alt="USB Devices power summary" class="screen"></p><p>Below the list, <strong>POWER</strong> sets the summary apart. <strong>TOTAL</strong> adds up every row, hubs included. <strong>USB-C INPUT</strong> shows what your computer or charger offers: <strong>500 mA</strong>, <strong>1.5A</strong>, or <strong>3.0A</strong>. When <strong>TOTAL</strong> is higher than the <strong>380 mA</strong> the USB Host port can supply, make sure they go through a powered USB hub.</p><h2 id="migrate-all-projects" tabindex="-1">Migrate All Projects <a class="header-anchor" href="#migrate-all-projects" aria-label="Permalink to &quot;Migrate All Projects&quot;">​</a></h2><p>After a firmware update, projects saved by the previous firmware version are still on your S32 but are stored in the older format. Loading one asks <strong>Update project to current version?</strong> and updates just that project. <strong>Migrate All Projects</strong> does the same for every out-of-date project at once, across <strong>internal storage and microSD</strong>.</p><p>Select it and the S32 first checks each project, then asks how many it is about to update.</p><p><img src="'+u+'" alt="Migrate All Projects confirmation" class="screen"></p><p>Press <strong>Select</strong> (<strong>UPDATE</strong>) to start, or <strong>Back</strong> to leave everything untouched. If the active project has unsaved edits you are asked to save or discard them first.</p><p>A progress bar and a count (<strong>PROJECT 4 OF 12</strong>) track the batch and block the controls until it finishes.</p><p><img src="'+f+'" alt="Migrate All Projects progress" class="screen"></p><p>When it finishes, a summary shows what happened.</p><p><img src="'+v+'" alt="Migrate All Projects summary" class="screen"></p><table tabindex="0"><thead><tr><th>Count</th><th>Meaning</th></tr></thead><tbody><tr><td>Updated</td><td>Projects rewritten in the current format</td></tr><tr><td>Skipped</td><td>Too old or too new to update (see below) — projects that were already up to date are not counted here</td></tr><tr><td>Failed</td><td>Could not be read or written — the original project is left as it was</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Projects that cannot be updated</p><p>The S32 only updates projects saved by the <strong>immediately previous</strong> firmware version.</p><ul><li><strong>Project needs older firmware first</strong> — saved by a much older firmware. Install the intermediate firmware version, open the project once so it updates, then return to the current firmware.</li><li><strong>Project needs newer firmware</strong> — saved by a firmware version newer than the one installed. Update the S32 firmware.</li></ul><p>Both are reported as <em>skipped</em>; nothing is written to them. The same messages at boot leave that project on storage: <strong>Save Project</strong> does not overwrite the slot with the empty set shown on Perform.</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li>Leave the microSD card inserted for the whole batch — projects on a card that is removed part-way are reported as failed and stay in the old format.</li><li>Nothing is deleted. Projects are rewritten in place, keeping their name and storage location.</li><li>Projects from 0.17 keep clock, channel, encoder, and tempo. Snapshot pads start empty — TAKE new scenes after you update.</li><li>Running the action again is safe; projects already updated are simply skipped.</li></ul></div>',31)),l(s,null,{default:c(()=>[...t[0]||(t[0]=[e("ul",null,[e("li",null,[e("a",{href:"./storage-info"},"Storage Info"),r(" — Usage display and format")]),e("li",null,[e("a",{href:"./../projects/"},"Project"),r(" — Clock, channel, encoder, save, and library")]),e("li",null,[e("a",{href:"./../perform/knob-view"},"Perform View"),r(" — BPM and tap tempo from Perform")]),e("li",null,[e("a",{href:"./../getting-started/troubleshooting"},"Troubleshooting"),r(" — Settings and storage messages")])],-1)])]),_:1})])}const T=o(w,[["render",b]]);export{A as __pageData,T as default};
